   ```js
   const helmet = require('helmet');
   const cors   = require('cors');
   const rateLimit = require('express-rate-limit');
   const morgan = require('morgan');

   app.use(helmet());
   app.use(cors({ origin: process.env.CORS_ORIGIN || '*' }));
   app.use(rateLimit({ windowMs: 15*60*1000, max: 100 }));
   app.use(express.json({ limit: '1mb' }));
   app.use(morgan('combined'));
   ```

3. **Add a generic error handler** at the bottom of the file:

   ```js
   app.use((err, req, res, next) => {
     const isProd = process.env.NODE_ENV === 'production';
     const status = err.status || err.statusCode || 500;
     console.error(err);
     res.status(status).json({
       error: {
         message: isProd ? 'Internal Server Error' : err.message,
         ...( !isProd && { stack: err.stack } ),
       },
     });
   });
   ```

4. **Add validation for any route that accepts user input** – e.g., a POST `/users`:

   ```js
   const { celebrate, Joi, Segments } = require('celebrate');

   const userSchema = celebrate({
     [Segments.BODY]: Joi.object({
       name: Joi.string().min(1).max(100).required(),
       email: Joi.string().email().required(),
     }),
   });

   app.post('/users', userSchema, async (req, res) => {
     // safe to use req.body now
   });
   ```

5. **Replace the hard‑coded port** with an env var and add graceful shutdown (optional but recommended for production).

