// ---------------------------------------------------------------------------
// app.js – enhanced with security hardening, validation, and centralized error handling
// ---------------------------------------------------------------------------

require('dotenv').config();               // Load .env (PORT, NODE_ENV, etc.)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ---------------------------------------------------------------
// Middleware stack
// ---------------------------------------------------------------
app.use(helmet());                         // Secure HTTP headers
app.use(express.json());                  // Body parser for JSON payloads

// CORS – tighten in prod, open for dev
const corsOptions = {
  origin: process.env.CORS_ORIGIN?.split(',') || false, // e.g. "https://myapp.com"
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
};
app.use(cors(corsOptions));

// Logging – morgan in 'combined' format (good for production)
// Optionally pipe to a file/remote logger in real deployments
app.use(morgan('combined'));

// Rate limiting – 100 requests per 15 min per IP (tune as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------------------------------------------------------------
// Helper: validation result checker
// ---------------------------------------------------------------
function checkValidation(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Return the first error (or you can return the whole array)
    return res.status(400).json({ error: 'Invalid request', details: errors.array() });
  }
  next();
}

// ---------------------------------------------------------------
// Routes
// ---------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example of a GET endpoint that *could* accept query parameters.
 * Validation is shown even though currently we accept none.
 */
app.get(
  '/users',
  // Example validation: ?page=2&limit=10
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    checkValidation,
  ],
  (req, res, next) => {
    try {
