      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];
      res.json(users);
    } catch (err) {
      next(err); // Forward to the centralized error handler
    }
  }
);

/**
 * NEW: POST /users – demonstrates input validation and sanitisation.
 */
app.post(
  '/users',
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Must be a valid email address'),
    checkValidation,
  ],
  (req, res, next) => {
    try {
      // Simulate DB insert & respond with the created record
      const { name, email } = req.body;
      const newUser = { id: Date.now(), name, email };
      // In a real service you would handle duplicate‑email checks, etc.
      res.status(201).json(newUser);
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------
// Centralized error handling middleware
// ---------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full error (stack) in dev, but not to the client
  console.error(err);

  // Decide what to expose based on environment
  const safeMessage =
    process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message;

  // Optionally attach a UUID/correlation ID for tracing
  const correlationId = req.headers['x-correlation-id'] || null;

  res.status(err.status || 500).json({
    error: safeMessage,
    ...(correlationId && { correlationId }),
  });
});

// ---------------------------------------------------------------
// Server start – use env var for the port, fallback to 3000
// ---------------------------------------------------------------
