    return res.status(404).json({ error: err.message });
  }

  // Default: unexpected server error.
  // Log full error stack for ops, but never send it to the client.
  console.error(err); // Replace with a proper logger in production
  res.status(500).json({ error: 'Internal server error' });
});

/* -------------------------------------------------------------
 * 5️⃣  Server start (with graceful shutdown)
 * ------------------------------------------------------------- */
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on http://0.0.0.0:${PORT}`);
});

/* Graceful shutdown – close open connections before exiting */
function shutdown(signal) {
  console.log(`\nReceived ${signal}. Closing server...`);
  server.close(() => {
    console.log('Server closed. Exiting process.');
