function validate(schema, property = 'body') {
  return (req, res, next) => {
    const { error, value } = schema.validate(req[property], { abortEarly: false, stripUnknown: true });
    if (error) {
      // Convert Joi details into a clean error payload
      const err = new Error('Invalid request data');
      err.status = 400;
      err.details = error.details.map(d => d.message);
      return next(err);
    }
    // Replace the original object with the sanitized value
    req[property] = value;
    next();
  };
}

// Example usage on a hypothetical POST /users
const userSchema = Joi.object({
  name: Joi.string().trim().min(2).max  (50).required(),
  email: Joi.string().email({ tlds: { allow: false } }).required(),
  // any other fields, with sanitisation (e.g., .escape() for strings if needed)
});

app.post('/users', validate(userSchema), async (req, res, next) => {
  try {
    const created = await UserModel.create(req.body); // assume async DB call
    res.status(201).json(created);
  } catch (e) {
    next(e);
  }
});
```

* **Why Joi (or Zod, Yup, AJV, etc.)?** It automatically strips unknown keys, lets you impose length limits, regex patterns, and custom sanitizers—critical for preventing injection attacks (SQL/NoSQL, command injection, etc.).  
* **Never trust query strings, headers, or URL params** – validate them as well. Example for `req.params.id`:

```js
