## 4️⃣ Putting It All Together – Refactored `app.js`

```js
// ----------------------------------------------------
// app.js – Hardened Express entry point
// ----------------------------------------------------
require('dotenv').config();               // load .env files (dev convenience)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');

// ------------------ Logger ---------------------------
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

// ------------------ App ------------------------------
const app = express();

// ------------ Global Middleware ----------------------
app.use(helmet());                                     // security headers
app.use(cors({                                         // restrict origins
  origin: process.env.CORS_ORIGIN || '*',            // change '*' to whitelist in prod
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
}));
app.use(rateLimit({                                   // basic DoS protection
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));
app.use(express.json({ limit: '1mb' }));               // body parsing + size limit
app.use(express.urlencoded({ extended: false, limit: '1mb' }));

// request‑level logging (simple)
app.use((req, res, next) => {
  logger.info({ method: req.method, url: req.originalUrl, ip: req.ip });
  next();
});

// ------------------ Routes ---------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app this would be a DB call. Keeping static data for demo.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ------------- Central Error Handler -----------------
app.use((err, req, res, next) => {
  const status = err.status || 500;
  // Log full error internally (stack, etc.)
  logger.error({ err, url: req.originalUrl, method: req.method });

  // Never leak stack traces in production
  const message = status === 500 ? 'Internal Server Error' : err.message;
  const payload = { error: { message } };

  // Optionally expose validation details for 4xx errors
  if (err.details) payload.error.details = err.details;

  res.status(status).json(payload);
});

// ------------------ Server Start ---------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// ------------ Graceful shutdown ----------------------
function gracefulShutdown(signal) {
  logger.info(`${signal} received – shutting down…`);
  server.close(() => {
    logger.info('HTTP server closed.');
    process.exit(0);
  });
}
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT',  () => gracefulShutdown('SIGINT'));

// ----------------- Process‑wide error handling --------
process.on('unhandledRejection', (reason) => {
  logger.error('Unhandled Promise Rejection:', reason);
  // option: attempt graceful shutdown or just log
});
process.on('uncaughtException', (err) => {
  logger.fatal('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;
```

### What changed?

| Change | Security / Reliability benefit |
|--------|---------------------------------|
| **helmet, cors, rate‑limit** | Harden HTTP surface and mitigate abuse |
| **express.json/.urlencoded with size limits** | Stops oversized payload attacks |
| **pino logger** | Structured logs, easy to route to ELK/Splunk; no `console.log` in production |
| **Central error middleware** | Guarantees consistent JSON errors, hides stack traces, logs internally |
| **Graceful shutdown + process‑wide handlers** | Prevents zombie processes and makes failures observable |
| **Environment‑driven config** | No hard‑coded port, allows secret management outside code |
| **Skeleton for validation middleware** | Makes it trivial to add Joi/Zod checks for any future endpoint |

