  // Avoid leaking internal details – send a generic message
  const status = err.status || 500;
  res.status(status).json({
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
    },
  });
});
```

### 1.3 Graceful Shutdown & Uncaught Exception Handling  

```js
// Capture unexpected rejections / exceptions
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // You might decide to shut down the process after logging
