```js
// ====================== app.js – hardened version ======================

// Core modules
const express = require('express');
const helmet = require('helmet');               // HTTP security headers
const cors = require('cors');                   // CORS handling
const rateLimit = require('express-rate-limit'); // Simple DoS protection
const morgan = require('morgan');               // Structured request logging
require('express-async-errors');                // Auto‑forward async errors to error‑handler

const app = express();

// ---------------------------------------------------------------------
// 1️⃣ Global middleware (security, parsing, logging)
// ---------------------------------------------------------------------
app.disable('x-powered-by');                     // Hide Express fingerprint

app.use(helmet());                               // Set > 12 security headers
app.use(
  cors({
    // Update the origin list to match your client domains
    origin: ['https://my-frontend.example.com'],
    methods: ['GET', 'HEAD', 'OPTIONS'],
    // credentials: true, // enable if you need cookies / auth headers
  })
);

app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,                 // limit each IP to 100 requests per window
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, please try again later.' },
  })
);

// Limit request body size (good practice even for GET-only APIs)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Structured request logging (only in dev you might want 'dev' format)
app.use(
  morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev')
);

// ---------------------------------------------------------------------
// 2️⃣ Routes – keep original behaviour, but guard against future input
// ---------------------------------------------------------------------
app.get('/health', (req, res) => {
  // No user input → nothing to validate
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Example of *future* query‑parameter validation:
  //   const { page = 1, limit = 10 } = req.query;
  //   // Validate with Joi/Zod here before using them
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---------------------------------------------------------------------
// 3️⃣ Centralised error handling
// ---------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the error (could be replaced by winston/pino)
  console.error(err);

  // Do **not** leak stack traces in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const payload = {
    error: isProd ? 'Internal Server Error' : err.message,
  };
  if (!isProd && err.stack) {
    payload.stack = err.stack;
  }
  res.status(status).json(payload);
});

// ---------------------------------------------------------------------
// 4️⃣ Server bootstrap (environment‑driven port + graceful shutdown)
// ---------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});

// Graceful shutdown – helps with containers/orchestrators
function shutDown() {
  console.log('⚙️  Graceful shutdown initiated...');
  server.close(() => {
    console.log('✅ HTTP server closed.');
    process.exit(0);
  });
  // Force exit after 10 seconds
  setTimeout(() => process.exit(1), 10_000);
}
process.on('SIGTERM', shutDown);
process.on('SIGINT', shutDown);
process.on('uncaughtException', (err) => {
  console.error('❗ Uncaught Exception:', err);
  shutDown();
});
process.on('unhandledRejection', (reason) => {
  console.error('❗ Unhandled Rejection:', reason);
  shutDown();
});

module.exports = app;
```

